import functools, time

def retry(times=3, delay=1.0, backoff=2.0, exc=Exception):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            d = delay
            for i in range(times):
                try:
                    return fn(*a, **kw)
                except exc:
                    if i == times - 1:
                        raise
                    time.sleep(d)
                    d *= backoff
        return wrapper
    return deco
```

