def flatten(d, prefix=""):
    out = {}
    for k, v in d.items():
        key = f"{prefix}.{k}" if prefix else k
        if isinstance(v, dict) and v:
            out.update(flatten(v, key))
        elif isinstance(v, dict):
            out[key] = {}
        else:
            out[key] = v
    return out
